@media (max-width: 900px) {
    .topbar { gap: 12px; padding: 0 12px; }
    .topbar-stats { display: none; }
    .mode-tab { padding: 8px 12px; font-size: 13px; }
    .server-bar { display: none; }
    .sidebar { width: 200px; }
    .bar-label { width: 90px; }
}

@media (max-width: 768px) {
    /* Sidebar becomes slide-in drawer */
    .discord-shell { position: relative; }
    .sidebar {
        position: fixed;
        top: 58px;
        bottom: 0;
        left: 0;
        width: min(82vw, 300px);
        z-index: 100;
        transform: translateX(-105%);
        transition: transform 0.25s ease;
        box-shadow: 4px 0 24px rgba(0, 0, 0, 0.5);
    }
    .discord-shell.sidebar-open .sidebar { transform: translateX(0); }
    .discord-shell.sidebar-open .sidebar-overlay { display: block; }
    .sidebar-toggle { display: flex; }

    .msg-group { padding: 4px 12px; gap: 10px; }
    .avatar { width: 34px; height: 34px; font-size: 14px; }
    .chat-header { padding: 10px 12px; }
    .chat-input-bar { padding: 0 12px 12px; }
    .date-divider { margin: 18px 12px 4px; }

    .search-shell { padding: 16px 14px 0; }
    .search-title, .facts-title { font-size: 21px; }
    .facts-shell { padding: 16px 14px 36px; }
    .facts-grid { grid-template-columns: 1fr; }
    .facts-hero { grid-template-columns: repeat(2, 1fr); gap: 8px; }
    .hero-stat { padding: 12px; }
    .hero-stat-value { font-size: 20px; }
}

@media (max-width: 640px) {
    .brand-name { display: none; }
    .search-row { flex-direction: column; }
    .user-select { max-width: none; }
    .mode-tab { padding: 8px 10px; }
    .mode-tab svg { width: 16px; height: 16px; }
    /* Avoid iOS zoom on input focus */
    .search-input, .user-select { font-size: 16px; }
}

@media (max-width: 420px) {
    .mode-tab { gap: 5px; font-size: 12px; padding: 7px 8px; }
    .topbar { height: 52px; }
    .sidebar { top: 52px; }
    .bar-label { width: 72px; font-size: 12px; }
    .bar-count { width: 42px; }
}
